window.DR_DATA=window.DR_DATA||{};window.DR_DATA["guides"]=[{"id":"course-1130","title":"Status: Scorched","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants take constant Solar damage."}]},{"id":"course-2031","title":"Combatant Level","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The higher the combatant's level, the higher their damage and health."}]},{"id":"course-2230","title":"Dark Haze","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"High-density mimetic particles have filled this area. Exposure to them deals continuous corrosive damage. Activate bu will continue to cause erosion damage. Activate Light bud primordia to gain protection."}]},{"id":"course-1080","title":"Status: Damage Resist","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Reduces damage taken."}]},{"id":"course-2092","title":"Solar Enhancement","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Solar characters deal increased damage."}]},{"id":"course-1801","title":"Character Element: Arc","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Arc is the element of motion and conduction, and is created when the electromagnetic forces of our universe struggle to achieve balance."}]},{"id":"course-2051","title":"Enhanced Combatants","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants gain 10% increased health and deal 20% increased damage."}]},{"id":"course-1280","title":"Rare Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Rare weapons come with perks unlocked."}]},{"id":"course-2243","title":"Character Gilding Quests","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Each character has Bronze, Silver, and Gilded quests. Complete all quests in a tier to earn the corresponding medal, which can be used to break through Acclaim Level tiers and activate Acclaim bonuses."}]},{"id":"course-1802","title":"Character Element: Solar","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The Solar element is the nuclear force that scorches anyone foolish enough to draw near and is the same force we harness to heal."}]},{"id":"course-1803","title":"Character Element: Void","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Void is the element of cosmic distortion. It is the pull of gravity and the promise of entropy."}]},{"id":"course-2274","title":"Burn Out","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Two fireteams each hunt a boss. During the hunt, the boss will become invulnerable. Lightbearers must head to a neutral PvP zone and seize Scorch Cannons, which can be used to unlock their boss's health. The fireteam that defeats their boss first wins."}]},{"id":"course-1830","title":"Relic Upgrade","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You can upgrade your abilities in the Relic screen."}]},{"id":"course-2231","title":"Unstable Rocket Pod","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Mimetic particles automatically group to form rocket pods and dissipate once all reserves are fired."}]},{"id":"course-1840","title":"Weapon Mastery","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Usable weapon types may vary between different characters based on their Weapon Mastery."}]},{"id":"course-2245","title":"Foundry Medal Quests","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Complete Foundry Medal Quests to gain Acclaim. Collecting all of a foundry's medals also activates that foundry's powerful Origin Trait effect, improving its weapons' damage."}]},{"id":"course-2032","title":"Dynamic Level","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants' levels will change within a dynamic range based on your Team Level."}]},{"id":"course-2033","title":"Dynamic Level Advantage","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatant levels change based on your Team Level will always be lower than your Team Level. With Level Advantage active, you will deal higher damage and take less damage."}]},{"id":"course-2034","title":"Dynamic Level Suppression","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatant levels will dynamically change based on your Team Level."}]},{"id":"course-2216","title":"Tenacious Elites","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants in this instance have +100% health."}]},{"id":"course-2003","title":"Piercing Party","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face Piercing Shinkas.\n[2] Challengers will deal 50% increased damage with Piercing weapons."}]},{"id":"course-1620","title":"Double Jump","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Double jump to reach higher locations."}]},{"id":"course-1811","title":"Character Role: Offense","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A formidable powerhouse capable of inflicting devastating damage on their adversaries."}]},{"id":"course-2273","title":"Defusal","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A boss takes turns appearing in each fireteam's room. The fireteam the boss appears for must defeat the boss within the time limit. Afterwards, the boss will head to the next room. Fireteams that cannot defeat the boss in time will be eliminated."}]},{"id":"course-1812","title":"Character Role: Defense","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A resilient survivalist capable of counteracting relentless attacks and harsh combat environments."}]},{"id":"course-1941","title":"Jiangshi Metro","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"In the Golden Age, the Lanyue Aeronautic Campus of Jiangshi Metro was a hub of international space exploration and technology exchange."}]},{"id":"course-2240","title":"Acclaim Level","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Your Acclaim Level is a symbol of your progress. Complete Character Gilding Quests and Foundry Medal Quests to level up. As your Acclaim Level rises, you'll receive rewards and activate exclusive Acclaim bonuses!"}]},{"id":"course-1813","title":"Character Role: Support","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A force enhancer capable of offering extensive combat improvements to their allies through exceptional buffs or healing effects."}]},{"id":"course-1814","title":"Character Level","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You can use XP Crystals to upgrade a Lightbearer and boost their base attributes."}]},{"id":"course-1861","title":"2-Piece","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Equip 2 Shards of the same name to activate the 2-piece set bonus."}]},{"id":"course-1140","title":"Status: Suppressed","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Suppressed: All abilities are disabled."}]},{"id":"course-1981","title":"Arc Shield Legion","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You will face many foes with Arc elemental shields, which can be easily countered with Arc characters or weapons."}]},{"id":"course-1590","title":"Shielded Combatants","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Use the matching element to break elemental shields quickly."}]},{"id":"course-2041","title":"Equipment Locked","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You cannot change weapons or upgrade characters during the challenge."}]},{"id":"course-2217","title":"Fair Play","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"During this activity, all Lightbearers' Power, upgrades, etc. will be calibrated to the same level."}]},{"id":"course-1370","title":"Heavy Ammo","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Rare ammo that may drop from combatants.\nUsed by all Power weapons."}]},{"id":"course-1820","title":"Relic","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Every Lightbearer wields a Relic—an instrument that unleashes their unfathomable potential."}]},{"id":"course-1470","title":"Guard","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Hold the Guard button when using a Sword to reduce damage taken."}]},{"id":"course-2241","title":"Acclaim Level","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Once you reach a certain Acclaim Level, you'll need Character Medals to upgrade. These can be earned by completing Character Gilding Quests. Reaching the next tier only requires having the corresponding medals; breakthrough will not consume medals."}]},{"id":"course-1270","title":"Weapon Rarity","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Weapons are divided into 4 qualities: Rare, Legendary, Mythic, and Exotic. Weapons of higher qualities have higher base attributes, and weapons of different qualities have different sources."}]},{"id":"course-2242","title":"Character Gilding Quests","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Once you've acquired a character, select them on the Acclaim screen to view their Gilding Quests. Complete the challenges to earn both Acclaim XP and medals, which can be used to raise your Acclaim Level and unlock Acclaim bonuses."}]},{"id":"course-1150","title":"Status: Blinded","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants are disoriented and struggle to fire their weapons."}]},{"id":"course-2244","title":"Foundry Medal Quests","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"There are many foundries within the Armory. Select a foundry's card to view its Foundry Medal Quests."}]},{"id":"course-2052","title":"Random Combatant Race","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants of random races will appear during the challenge."}]},{"id":"course-1380","title":"Elemental Energy","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Elements include Arc, Solar, and Void, which can mainly be found in Relics and elemental weapons. Using Relic Abilities or elemental weapons to attack targets with a shield of the same element causes elemental match effects."}]},{"id":"course-1170","title":"Status: Accelerated","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Grants increased movement speed. Mid-air acceleration is a special type of acceleration."}]},{"id":"course-2246","title":"Acclaim Bonuses","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Acclaim Level includes multiple Acclaim Bonuses, which provide various buffs."}]},{"id":"course-2247","title":"Acclaim Bonuses","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Acclaim bonuses can be unlocked and upgraded by raising your Acclaim Level and spending Character Medals."}]},{"id":"course-1540","title":"Shinka","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"There are 4 types of Shinkas: Rapid-Fire, Spread, Piercing, and Impact. These are powerful combatants who must be countered using the corresponding weapon type. Once its shield is broken, the Shinka will be briefly stunned, and they will regenerate their shield after a short while."}]},{"id":"course-2250","title":"About Challenge Mode","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Challenge Mode features two different modifiers each week, as well as different stages with each cycle. Each activity includes combatants with different elemental shields, as well as different varieties of Shinkas."}]},{"id":"course-1160","title":"Status: Disable Heal","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Health regeneration and healing are disabled, but those affected can still gain overshields."}]},{"id":"course-2251","title":"About Matchmaking Restrictions","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"To conquer these perilous challenges, only Lightbearers who meet the activity's requirements may participate in matchmaking. Of course, powerful fireteams capable of tacit cooperation are also allowed to enter directly, with no need to meet member quotas or character restrictions."}]},{"id":"course-1570","title":"Trip Mine","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Detonates whenever someone comes into contact with the laser. Destroy it from a distance."}]},{"id":"course-1961","title":"Arc Shield","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You will face foes with Arc elemental shields, which can be easily countered with Arc characters or weapons."}]},{"id":"course-2252","title":"Rewards & Fatigue Mechanics","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"After completing an activity, Lightbearers can spend keys to claim Challenge Chest rewards. Doing so will also deduct the used character's Stamina; characters without stamina must wait until the next day to attempt the challenge again."}]},{"id":"course-2253","title":"Match Game","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants' elemental shields take 25% less damage from non-matching elements."}]},{"id":"course-2254","title":"Adverse Agreement","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Combatants' attacks will become significantly stronger as their health decreases. Characters with sturdy defensive capabilities are recommended."}]},{"id":"course-1390","title":"Elemental Shields","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Some combatants are armed with a restorable elemental shield that protects them from taking damage. When they haven't been hit for some time, their elemental shield will be restored."}]},{"id":"course-2260","title":"Season XP Acquisition","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Upon reaching Team Lv.80, excess XP earned will be automatically converted into Season XP. The Season XP cap increases along with your level and Season Phase, as well as daily."}]},{"id":"course-1290","title":"Legendary Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Legendary weapons come with perks unlocked, and you can equip mods to them."}]},{"id":"course-2261","title":"Season XP Acquisition","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Each Season Phase has its own corresponding quests, and all season quests provide Season XP."}]},{"id":"course-2070","title":"Pinnacle Energy","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You will recover 120 per day, until you reach capacity."}]},{"id":"course-2262","title":"Paragon XP Sources","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Raising your Season Rank is the only way to gain Paragon XP."}]},{"id":"course-1862","title":"4-Piece","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Equip 4 Shards of the same name to activate the 4-piece set bonus."}]},{"id":"course-2263","title":"Paragon Board","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Spend Paragon XP to activate nodes on the Paragon Board. Raise your Season Rank to acquire more Paragon XP, letting you activate more nodes and boost your combat capabilities."}]},{"id":"course-2071","title":"Pinnacle Energy Reserves","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"When your Pinnacle Energy is insufficient, you can use Pinnacle Energy Reserves to make up the rest."}]},{"id":"course-2072","title":"Consumes Energy","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Prioritizes consuming Pinnacle Energy. If it is insufficient, you can only claim few rewards."}]},{"id":"course-2091","title":"Arc Enhancement","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Arc characters deal increased damage."}]},{"id":"course-1400","title":"Elemental Match","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Attacks with elements different from the element elemental shield deal less damage.\nAttacks with the same element as the elemental shield deal more damage, and breaking the shield deals additional damage."}]},{"id":"course-2270","title":"Hypoxia","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The environment is filled with damaging mist, and waves of combatants will constantly appear. Lightbearers within the aura surrounding the Sentinel's Piece will avoid damage; however, combatants' attacks will lower its durability. If the Sentinel's Piece is destroyed, the fireteam will be eliminated."}]},{"id":"course-2271","title":"Data Mining","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Fireteams earn 1 point for each zone they capture. The guarding Minotaurs must be defeated to unlock the zone. Once time's up, the fireteam that has captured the fewest zones is eliminated."}]},{"id":"course-1973","title":"Void Surge","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face foes with Void elemental shields.\n[2] Void characters deal increased damage."}]},{"id":"course-2272","title":"Dare Dash","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"There are a total of 5 rooms in this match. Lightbearers must defeat each room's boss and place the Scorching Orb in the goal to teleport to the next room. For 5s after clearing a room, Lightbearers can throw obstacles into their opponents' environment. The fireteam that clears all rooms and reaches the finish line first advances."}]},{"id":"course-1312","title":"Catalyst","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Materials and Exotic weapons of the same name can be consumed to unlock a weapon's Catalyst, significantly boosting the weapon's attributes."}]},{"id":"course-2275","title":"Colosseum","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Two fireteams fight to seize Hive Swords in a PvP environment. Lightbearers holding Hive Swords continuously gain points, and using the Sword to break Hive crystals grants additional points. The first fireteam to reach the target score wins."}]},{"id":"course-1543","title":"Piercing Shinka","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Piercing Shinkas have a specific damage resistance mechanic that can usually be disabled by a quick hit on a specific part of its body. Can be countered with Piercing weapons."}]},{"id":"course-1410","title":"Precision Hit","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Attacking an adversary's weak spot inflicts precision damage (inapplicable to Fusion Rifles and Swords)."}]},{"id":"course-1860","title":"Artifacts","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Artifacts provide stat bonuses. A full set can even unlock special effects."}]},{"id":"course-2093","title":"Void Enhancement","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Void characters deal increased damage."}]},{"id":"course-1870","title":"Equipping Artifacts","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Equip artifacts to greatly increase a character's Power."}]},{"id":"course-1871","title":"Artifact Modification","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Artifacts can be modified via refactor, enhancement, and attribute transfer."}]},{"id":"course-1872","title":"Artifact Sources","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You can acquire many artifacts from the Realm of the IX."}]},{"id":"course-1200","title":"Weapon Slots","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Weapons can be equipped to 2 slots: Primary and Power."}]},{"id":"course-2101","title":"Commission Destinations","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Different destinations have their own exclusive daily commissions, and you may freely choose which destination's commissions you would like to complete. Note that changes made to your commission destination take effect the following day."}]},{"id":"course-2102","title":"Changing Destinations - Quests Incomplete","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"When you have incomplete daily commissions, you can switch destinations via the Daily Commissions tab on the Activities screen."}]},{"id":"course-2103","title":"Changing Destinations - Quests Complete","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"When your Destination Daily Quests for the day are completed, you can similarly switch destinations via the Recommended title on the Challenges screen."}]},{"id":"course-1430","title":"Ricochet","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Rounds bounce off hard surfaces."}]},{"id":"course-1880","title":"Talent Tree","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You can activate a variety of talents here, further strengthening a character's combat capabilities."}]},{"id":"course-1210","title":"Primary Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Weapons equipped to the first weapon slot. They use Primary ammo, which is in an infinite supply."}]},{"id":"course-1440","title":"Sticky","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Rounds attach on impact and explode shortly afterward."}]},{"id":"course-1890","title":"Modification: Attachment Remodeling","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You can spend Weapon Salvage to remodel weapon attachments or unlock more attachment options."}]},{"id":"course-1531","title":"Cabal","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The Cabal combatants may enter their combat stance to enhance their head-on battle capabilities. Use displacement-type character abilities to gain an upper hand against them."}]},{"id":"course-2120","title":"Gear Lv.","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"As your Team Level increases, your Gear Level will also steadily increase. Weapons with a higher Gear Level deal more damage."}]},{"id":"course-2121","title":"Gear Lv.","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Gear Level increases are only available for Exotic, Mythic, and Legendary weapons. Weapons of other rarities drop with a fixed Gear Level."}]},{"id":"course-1450","title":"Blast","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Deals damage to all targets in the blast radius."}]},{"id":"course-1900","title":"Modification: Weapon Enhancement","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Enhance your weapons for greater damage and additional perks."}]},{"id":"course-1230","title":"Power Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Powerful weapons equipped to the second weapon slot. They use Heavy ammo, which is in a limited supply."}]},{"id":"course-2130","title":"Intro to Mods","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Each weapon has three slots for mods: scope, magazine, and ammo. Equip corresponding mods to boost their capabilities. Mods apply to all identical weapons. Once a mod is equipped to a weapon, it cannot be transferred to a weapon of a different name, but it can be dismantled."}]},{"id":"course-1946","title":"Gifts of the Nine","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Clear stages in the Realm of the IX to earn Gifts of the Nine, which improve your combat capability. Gifts of the Nine are only effective during the challenge they're acquired in."}]},{"id":"course-2131","title":"Equipping Mods","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Equipping mods to weapons not only boosts their capabilities, but can also raise their Perk & Trait Level."}]},{"id":"course-2132","title":"Equipping Mods","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Equipped mods can gain boosts to their attributes and Power via refinement."}]},{"id":"course-1920","title":"Reputation Sources","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Aid a destination's people and complete activities there (daily commissions, public events, regional challenges, etc.) to earn that destination's Reputation. Accumulate Reputation to raise your Reputation Rank, a symbol of your contribution in the region."}]},{"id":"course-2133","title":"Perk Upgrade","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Exotic mods come with different perk upgrades when acquired. When the weapon they're equipped to has the same effect as the mod, it will gain an upgraded effect."}]},{"id":"course-1541","title":"Rapid-Fire Shinka","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Rapid-Fire Shinkas have a specific damage resistance mechanic that can usually be disabled by a high number of hits. Can be countered with Rapid-Fire weapons."}]},{"id":"course-1460","title":"Track","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Rounds lock onto targets. When the target moves, they will change their flight path accordingly."}]},{"id":"course-1910","title":"WORLD MAP","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You can check info on various destinations and fast travel on the World Map."}]},{"id":"course-1911","title":"MINI-MAP","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Check the mini-map to view nearby hostiles, allies, quests, chests, puzzles, and more."}]},{"id":"course-2140","title":"Light-Linked Companions","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Light-Linked Companions provide different Light's Blessings for your deployed character. Configure your team wisely to gain an edge in battle."}]},{"id":"course-1921","title":"Reputation Rank Rewards","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Each destination's leader will reward those willing to help their territory overcome its troubles."}]},{"id":"course-1700","title":"Dualism","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The area is filled with chaotic mimetic particles. At least 2 Lightbearers must stay near the repair particles to resist the corrosion. Leaving the repair particles' range will cause you to sustain continuous corrosive damage."}]},{"id":"course-2150","title":"Combat Style","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Different Lightbearers excel at different ranges. Fight at their optimal range to make battles a breeze."}]},{"id":"course-1480","title":"Public Events","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Public events are multi-player activities available in various destinations. Participate to get a reward upon completion."}]},{"id":"course-1930","title":"Haven","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Haven is a new human settlement that was founded less than 20 years ago."}]},{"id":"course-1931","title":"Haven","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"After discovering the Traveler and \"The City\" beneath it, Lord Radegast moved his headquarters to where Haven is currently situated."}]},{"id":"course-1932","title":"Haven","sub":"Tutorial page · variant 3","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Haven is one of the essential routes to \"The City\"."}]},{"id":"course-1542","title":"Spread Shinka","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Spread Shinkas have a specific damage resistance mechanic that can usually be disabled by hitting multiple parts of its body at the same time. Can be countered with Spread weapons."}]},{"id":"course-1933","title":"Haven","sub":"Tutorial page · variant 4","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A miraculous creation of the Golden Age, a\"Sentinel,\" is still patrolling near Haven, carrying out its mission of protecting humanity."}]},{"id":"course-1710","title":"Malevolent Dome","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Mimetic particles will regularly generate protective barriers around combatants. Enter them and destroy their cores to remove the barrier."}]},{"id":"course-1934","title":"Haven","sub":"Tutorial page · variant 5","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Haven's unique geographical location has made it a hub for Lightbearers to gather and form communities."}]},{"id":"course-2160","title":"Power","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"This value represents a Lightbearer's attributes and combat capabilities. You must meet certain Power thresholds to take on some of the more dangerous missions..."}]},{"id":"course-1940","title":"Jiangshi Metro","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Jiangshi Metro is located in the highlands of South Asia. The stable climate and altitude advantages make it an ideal rocket launch site."}]},{"id":"course-1942","title":"Jiangshi Metro","sub":"Tutorial page · variant 3","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"In the Dark Age, Jiangshi Metro and its surrounding territories were once ruled by a callous Exo Warlord."}]},{"id":"course-1544","title":"Impact Shinka","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Impact Shinkas have a specific damage resistance mechanic that can usually be disabled by close-range attacks. Can be countered with Impact weapons."}]},{"id":"course-1943","title":"Jiangshi Metro","sub":"Tutorial page · variant 4","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Jiangshi Metro was one of the first human settlements to be attacked by the Fallen during the Dark Age."}]},{"id":"course-1944","title":"Jiangshi Metro","sub":"Tutorial page · variant 5","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Although Jiangshi Metro is nominally under the Iron Lords' rule, it enjoys a high degree of autonomy and is protected by a resilient militia."}]},{"id":"course-1720","title":"Excessive Radiation","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Chaotic mimetic particles will continuously generate radiation. Destroy particle condensates to regain your regenerative capabilities."}]},{"id":"course-1945","title":"Sparrow Racing","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Pilot your Sparrow to crush the competition!"}]},{"id":"course-1947","title":"Time and Rewards","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"These stages have a countdown. When the first countdown ends, combatants will become enraged, and a death countdown will begin. Once time is up, your Light will fade away.\nIn Singularity: Order, you will earn greater rewards for faster completions."}]},{"id":"course-1505","title":"Weapon Style: Impact","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Slot 2 weapons for this style are Shotguns, Fusion Rifles, and Swords."}]},{"id":"course-1050","title":"Overshield","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A special shield that grants damage resistance on top of health and the normal shield."}]},{"id":"course-2210","title":"Relic Reset","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Until you complete Chapter 7-2, you can reset upgraded Relic Abilities."}]},{"id":"course-1501","title":"Weapon Style: Rapid-Fire","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Slot 1 weapons for this style are Auto Rifles, Submachine Guns, and Pulse Rifles. Slot 2 weapons for this style are Machine Guns and Auto Crossbows."}]},{"id":"course-1502","title":"Weapon Style: Spread","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Slot 1 weapons for this style are Light Grenade Launchers. Slot 2 weapons for this style are Grenade Launchers and Rocket Launchers."}]},{"id":"course-1503","title":"Weapon Style: Piercing","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Slot 1 weapons for this style are Scout Rifles and Hand Cannons. Slot 2 weapons for this style are Sniper Rifles."}]},{"id":"course-1948","title":"Singularity Rewards","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"In Singularity: Order, clearing stages grants first clear rewards. Finishing in less than 10 and 15 minutes grants an additional Golden and Silver Chest respectively."}]},{"id":"course-1730","title":"Particle Detainment","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Lightbearers detained by mimetic particles will be unable to attack and take constant damage."}]},{"id":"course-1950","title":"Finishers","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Finishers can be used to quickly take down low-health combatants."}]},{"id":"course-2170","title":"Proficiency","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Once you've acquired a character, you can raise their Proficiency by using them to complete daily commissions, spend Pinnacle Energy, and complete activities."}]},{"id":"course-1060","title":"Status: Being Healed","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Receiving healing effects."}]},{"id":"course-1510","title":"Kinetic Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Element-less weapons. They deal 10% increased damage to combatants without an elemental shield."}]},{"id":"course-1962","title":"Solar Shield","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You will face foes with Solar elemental shields, which can be easily countered with Solar characters or weapons."}]},{"id":"course-1963","title":"Void Shield","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You will face foes with Void elemental shields, which can be easily countered with Void characters or weapons."}]},{"id":"course-1964","title":"Bounties: Accept","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Three bounties are granted upon daily login, and you can hold up to 9 at a time. Each bounty can be reset 4 times per day."}]},{"id":"course-1965","title":"Bounties: Rewards","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Bounties grant a lot of Material Rewards and increase Battle Pass Rank."}]},{"id":"course-2002","title":"Spread Party","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1]You will face Spread Shinkas.\n[2]Challengers will deal 50% increased damage with Spread weapons."}]},{"id":"course-2171","title":"Character Quest","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Raise characters' Proficiency to unlock their exclusive quests."}]},{"id":"course-2172","title":"Proficiency Upgrade Rewards","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Reaching certain Proficiency levels unlocks dynamic emotes."}]},{"id":"course-1070","title":"Status: Damage Bonus","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Increases weapon or ability damage."}]},{"id":"course-1520","title":"Elemental Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Weapons with an elemental affinity. They deal additional damage to combatant shields if the elements match."}]},{"id":"course-1971","title":"Arc Surge","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face foes with Arc elemental shields.\n[2] Arc characters deal increased damage."}]},{"id":"course-1972","title":"Solar Surge","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face foes with Solar elemental shields.\n[2] Solar characters deal increased damage."}]},{"id":"course-1300","title":"Mythic Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Mythic weapons come with higher quality perks unlocked, and you can equip mods to them."}]},{"id":"course-1750","title":"Weapon Perks—Pachinko","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A weapon's perk is its most powerful attribute. This Grenade Launcher's perk is: Pachinko — When the magazine is full, the first round will fire three additional grenades, and the blast radius is increased by 20%."}]},{"id":"course-2180","title":"Shield","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Shields are an additional way of taking damage that all Lightbearers have. There are also shield-related Gifts of the Nine in The Expanse."}]},{"id":"course-2190","title":"Team Level","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"As you raise your Team Level, you will gain large attribute bonuses, unlock higher Reward Levels, and raise upgrade caps."}]},{"id":"course-2191","title":"Team Level","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Higher reward levels yield better rewards when completing challenges."}]},{"id":"course-1530","title":"Fallen","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Fallen combatants may inflict Blind, Suppression, or Disable Heal. These negative effects can be removed by purification-type character abilities."}]},{"id":"course-1532","title":"Vex","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The Vex combatants may enter overclock status to gain significant damage resistance and special abilities. Use suppression-type character abilities to disrupt their overclocking."}]},{"id":"course-1533","title":"Hive","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The Hive combatants inflict Dark Energy on their targets when dealing damage. Sustained damage and a permanent curse will be applied to those afflicted with full Dark Energy. Use healing or shield effects empowered by the Light to remove the curse."}]},{"id":"course-1310","title":"Exotic Weapons","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Exotic weapons come with their most optimal perks automatically unlocked. Exotic refinement is also available."}]},{"id":"course-1982","title":"Solar Shield Legion","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You will face many foes with Solar elemental shields, which can be easily countered with Solar characters or weapons."}]},{"id":"course-1983","title":"Void Shield Legion","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"You will face many foes with Void elemental shields, which can be easily countered with Void characters or weapons."}]},{"id":"course-1311","title":"Exotic Refinement","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Exotic refinement includes Exotic Catalysts and Catalysis Boosts. All enhancements made to Exotic weapons apply to all weapons of the same name."}]},{"id":"course-1320","title":"Weapon Perks","sub":"Tutorial page · variant 1","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"When non-Exotic weapons are acquired, they come with random perks that provide additional effects when certain requirements are met."}]},{"id":"course-1321","title":"Intrinsic Trait","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Traits that weapons are guaranteed to come with when acquired. Different weapons have different intrinsic traits, which grant boosts to the weapon's rate of fire, damage, magazine capacity, and more."}]},{"id":"course-1322","title":"Origin Trait","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Traits unlocked by acquiring Foundry Medals. Weapons from the same foundry share the same origin trait, which grants the foundry's weapons high damage bonuses or special combat mechanics."}]},{"id":"course-1323","title":"Perks","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"When weapons are acquired, they come with random perks. Different perks are suitable for different combat scenarios."}]},{"id":"course-1991","title":"Arc Surge—Enhanced","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face many foes with Arc elemental shields.\n[2] Arc characters deal increased damage."}]},{"id":"course-1992","title":"Solar Surge—Enhanced","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face many foes with Solar elemental shields.\n[2] Solar characters deal increased damage."}]},{"id":"course-1993","title":"Void Surge—Enhanced","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face many foes with Void elemental shields.\n[2] Void characters deal increased damage."}]},{"id":"course-2001","title":"Rapid-Fire Party","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face Rapid-Fire Shinkas.\n[2] Challengers will deal 50% increased damage with Rapid-Fire weapons."}]},{"id":"course-1330","title":"Weapon Attachments","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Attachments grant a weapon improved range, magazine, reload speed, and more."}]},{"id":"course-2004","title":"Impact Party","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"[1] You will face Impact Shinkas.\n[2] Challengers will deal 50% increased damage with Impact weapons."}]},{"id":"course-2015","title":"Super Fatality","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Super final blows grant additional points."}]},{"id":"course-1313","title":"Catalysis Boost","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Consume materials to boost a weapon's performance."}]},{"id":"course-2200","title":"Take Photo","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Photography—the best choice for recording precious memories."}]},{"id":"course-2011","title":"Airborne Fatality","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Airborne final blows grant additional points."}]},{"id":"course-2012","title":"Precision Fatality","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Precision final blows grant additional points."}]},{"id":"course-2013","title":"Signature Fatality","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Signature ability final blows grant additional points."}]},{"id":"course-2211","title":"Relic Reset","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Resetting returns 100% of Glimmer and upgrade materials spent."}]},{"id":"course-1340","title":"Weapon Perks","sub":"Tutorial page · variant 2","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Mythic and Legendary weapons have random perks that provide additional effects when certain requirements are met."}]},{"id":"course-2212","title":"Close Range Combat","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Use characters suited for close range combat for an easier battle."}]},{"id":"course-2213","title":"Medium Range Combat","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Use characters suited for medium range combat for an easier battle."}]},{"id":"course-2214","title":"Long Range Combat","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Use characters suited for long range combat for an easier battle."}]},{"id":"course-2021","title":"Solar Wind","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Beams of high-energy particles will intermittently sweep through the area where the Lightbearers are located. All Lightbearers must enter a spherical shield to take shelter from the solar wind when it comes. Lightbearers who are exposed to it will be subjected to a constant barrage of high-energy particles until they die."}]},{"id":"course-2022","title":"Gravitational Singularity","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"A singularity of ever-expanding size and density with infinitely-growing gravitational force will suddenly appear. It will keep expanding until it consumes everything if it is not dealt with in time. Anything that gets near its center will be torn apart by its immense power. Firing at the singularity can reverse its expansion and destroy it."}]},{"id":"course-2023","title":"Electrical Breakdown","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"Faulty simulation algorithms cause charges far exceeding normal amounts to begin accumulating on Lightbearers. If two Lightbearers with ultra-high voltages get close to each other, an electrical breakdown will occur, causing both of them to take constant damage until they are a safe distance from each other."}]},{"id":"course-2215","title":"Tenacious Bosses","sub":"Tutorial page","quality":null,"art":null,"filters":{"Kind":"Tutorial page"},"body":[{"p":"The final boss in this instance has +50% health."}]},{"id":"tip-4-2","title":"Fireteams","sub":"Loading tip · variant 1","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A group of Lightbearers working together is known as a Fireteam. Join together and overcome impossible odds."}]},{"id":"tip-4-1","title":"Packs","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Many hands produce a stronger flame. Within a Pack, you may find friends who share your ambitions."}]},{"id":"tip-4-4","title":"Rewards","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"When claiming activity rewards, weekly high-value reward attempts will be spent first. If those have been exhausted, you will receive completion rewards."}]},{"id":"tip-12-3","title":"Massive Skeleton","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"The locals claim that people who approach these bones hear faint whispers and see strange illusions—bad omens, in their eyes."}]},{"id":"tip-12-1","title":"Veridian Union","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Veridia's true governing body, formed by the representatives of Veridia's industries."}]},{"id":"tip-12-2","title":"Veridia","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A human settlement built beneath the wreckage of the largest cargo ship in the Red Sea Rift, \"The Veridia.\""}]},{"id":"tip-12-4","title":"Firebase Minos","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"The first group of structures the Sand Eaters built when they arrived at the Red Sea Rift. It serves as their local command center."}]},{"id":"tip-12-5","title":"Veridia Forest","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A human-occupied region in the Red Sea Rift, named a \"forest\" due to the numerous wind-worn stone pillars dotting it."}]},{"id":"tip-12-6","title":"World Map","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"You can check info on various destinations and fast travel on the World Map."}]},{"id":"tip-12-7","title":"Reputation Sources","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Aid residents of destinations and complete activities there (daily commissions, public events, regional challenges, etc.) to earn that destination's Reputation. Accumulate Reputation to raise your Reputation Rank, a symbol of your contribution in the region."}]},{"id":"tip-12-9","title":"Treasure","sub":"Loading tip · variant 1","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Many legacies of the Golden Age are scattered throughout the world, offering unimaginable surprises to those who seek them out."}]},{"id":"tip-12-14","title":"Training Ground","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A place where many Lightbearers come to hone their skills."}]},{"id":"tip-12-15","title":"The Traveler","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"The creator of the Ghosts and the source of the Lightbearers' Light."}]},{"id":"tip-12-16","title":"The Light","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A paracausal force gifted to humanity by the Traveler. It brings complexity and diversity and is capable of creating matter and harboring life."}]},{"id":"tip-12-17","title":"Ghost","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"The Ghosts are the bridge between Lightbearers and the Light."}]},{"id":"tip-12-18","title":"Lightbearers","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Beings able to wield Arc, Solar, and Void forces with their flesh and blood."}]},{"id":"tip-1-4","title":"Treasure","sub":"Loading tip · variant 2","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Many legacies of the Golden Age are scattered throughout the world. They may offer unimaginable surprises to those who seek them out."}]},{"id":"tip-1-5","title":"Mini-Map","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Check the mini-map to view nearby hostiles, allies, quests, chests, puzzles, and more."}]},{"id":"tip-1-13","title":"Lightbearer","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Beings able to wield Arc, Solar, and Void forces with their flesh and blood."}]},{"id":"tip-2-2","title":"Haven","sub":"Loading tip · variant 1","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"After encountering the Traveler and \"The City\" beneath it, Radegast moved his headquarters to where Haven is currently situated."}]},{"id":"tip-2-1","title":"Haven","sub":"Loading tip · variant 2","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Although it was constructed within a ruin that predates the Collapse, Haven is a relatively new human settlement. It also serves as the stronghold of Iron Lord Radegast."}]},{"id":"tip-2-3","title":"Haven","sub":"Loading tip · variant 3","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"One must pass through Haven to reach \"The City.\""}]},{"id":"tip-2-4","title":"Haven","sub":"Loading tip · variant 4","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A miraculous creation of the Golden Age, the \"Sentinel,\" is still patrolling near Haven. Very few know how or why it was created."}]},{"id":"tip-2-5","title":"Haven","sub":"Loading tip · variant 5","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Haven's strategic location, isolated yet not lonely, has made it a hub for Lightbearers to gather and form communities."}]},{"id":"tip-3-1","title":"Jiangshi Metro","sub":"Loading tip · variant 1","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Jiangshi Metro is located in the highlands. The stable climate and altitude advantages make it an ideal rocket launch site."}]},{"id":"tip-3-5","title":"Jiangshi Metro","sub":"Loading tip · variant 2","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Although Jiangshi Metro is nominally under the Iron Lords' rule, it enjoys a high degree of autonomy and is protected by a resilient militia."}]},{"id":"tip-5-3","title":"Character Element: Solar","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Solar is the nuclear force that scorches anyone foolish enough to draw near, but it is also a force capable of mending wounds."}]},{"id":"tip-5-9","title":"Selecting Gifts of the Nine","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Clear stages in the Realm of the IX to earn Gifts of the Nine, which improve your combat capability. Gifts of the Nine are only effective during the challenge they're acquired in."}]},{"id":"tip-6-2","title":"Fireteams","sub":"Loading tip · variant 2","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Find suitable teammates to greatly boost your chances of a successful clear."}]},{"id":"tip-6-8","title":"Arc Surge—Enhanced","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"[1] You will face many foes with Arc elemental shields.\n[2] Challengers deal 50% increased Arc damage."}]},{"id":"tip-6-9","title":"Solar Surge—Enhanced","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"[1] You will face many foes with Solar elemental shields.\n[2] Challengers deal 50% increased Solar damage."}]},{"id":"tip-6-10","title":"Void Surge—Enhanced","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"[1] You will face many foes with Void elemental shields.\n[2] Challengers deal 50% increased Void damage."}]},{"id":"tip-7-8","title":"Spread Party","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"[1] You will face Spread Shinkas.\n[2] Challengers will deal 50% increased damage with Spread weapons."}]},{"id":"tip-7-9","title":"Piercing Party","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"[1] You will face Piercing Shinkas.\n[2]Challengers will deal 50% increased damage with Piercing weapons."}]},{"id":"tip-8-9","title":"Eclipse Monolith","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"The Fallen orbital fortress resulting from the Splicer Archpriest Issakis's modifications of the Lanyue Space Station."}]},{"id":"tip-8-5","title":"Solving Puzzles","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Observe and understand the mechanics you encounter, solve puzzles, and find the way forward."}]},{"id":"tip-8-6","title":"Co-op","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Some challenges cannot be overcome alone. Facing them with a fireteam is key."}]},{"id":"tip-8-7","title":"Splicers","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A technological alliance of cutting-edge scientists among the Fallen."}]},{"id":"tip-8-8","title":"Space Elevator","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"One of humanity's many Golden Age engineering marvels."}]},{"id":"tip-10-7","title":"Sync Gate","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Once the current area has been thoroughly searched, you can head to the next area via the Sync Gate."}]},{"id":"tip-10-1","title":"Data","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Defeating combatants, completing quests, and defeating opposing Lightbearers all drop Data."}]},{"id":"tip-10-2","title":"Infuse","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Store the Data you're carrying at the Transmission Terminal."}]},{"id":"tip-10-3","title":"Data Nucleus","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"A precious reward dropped by Prime Anomalies."}]},{"id":"tip-10-4","title":"Decipher","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Be mindful of your surroundings after acquiring a Data Nucleus. You may quickly become your enemies' main target."}]},{"id":"tip-11-4","title":"Nitrogen","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Hitting combatants and picking up items will hasten your nitrogen acquisition. Once your nitrogen is full, you'll gain an acceleration charge."}]},{"id":"tip-11-1","title":"Sparrow Racing Rewards","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Everyone has a chance to be rewarded with exclusive Mythic weapons."}]},{"id":"tip-11-2","title":"Accelerate","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Accelerate to boost your maximum speed."}]},{"id":"tip-11-3","title":"Sparrow Piloting","sub":"Loading tip","quality":null,"art":null,"filters":{"Kind":"Loading tip"},"body":[{"p":"Through countless daredevil stunts and close calls, almost every scout has become a master of Sparrow piloting. They can race at extreme speeds, execute hairpin turns, and perform highly risky acrobatics."}]},{"id":"train-998080","title":"Race Trait - Cabal","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cabal combatants use armaments to significantly increase their damage. Use blinding abilities to render them unable to aim."}]},{"id":"train-998017","title":"Mechanic Tutorial","sub":"Training lesson · variant 1","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Casting Signature Ability: Sidetrick generates a clone that attacks nearby combatants."}]},{"id":"train-998081","title":"Race Trait - Hive","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Hive combatants can heal themselves and their allies. Use corrupting abilities to interrupt their recovery."}]},{"id":"train-998065","title":"Mechanic Tutorial","sub":"Training lesson · variant 2","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"After casting Signature Ability: Shield of Starlight, once the shield hits combatants and returns to Jolder, it will grant her an overshield."}]},{"id":"train-998082","title":"Race Trait - Vex","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Vex combatants can overclock, gaining high damage resistance and special abilities. Use suppressing abilities to disrupt their overclocked status."}]},{"id":"train-998066","title":"Advanced Techniques","sub":"Training lesson · variant 1","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"While Weapon Mastery: Mayhem's Star is active, each hit that Jolder takes will grant a stack of Retribution. Hits landed while Jolder has Retribution will deal additional Void damage."}]},{"id":"train-998002","title":"Elemental Match","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Attacking combatants with the same element as their shield deals extra damage against the shield and creates an elemental explosion when the shield is destroyed."}]},{"id":"train-998068","title":"Advanced Techniques","sub":"Training lesson · variant 2","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"While Weapon Mastery: Mini Missile is active, reloading will load the new magazine with Mini Missiles, granting each shot an additional hit of Arc damage."}]},{"id":"train-998004","title":"Finisher","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Finishers can quickly eliminate certain low-health combatants."}]},{"id":"train-998069","title":"Mechanic Tutorial","sub":"Training lesson · variant 3","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Casting Signature Ability: Bewitched Illusion summons an illusion that will attack nearby combatants. Casting Signature Ability: Misfortune's Guide will guide the illusion to attack a specific combatant."}]},{"id":"train-998005","title":"Mechanic Tutorial","sub":"Training lesson · variant 4","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Using Signature Ability: Wolf's Strike to defeat a combatant immediately resets the ability's cooldown. Learn to cast your Signature Ability at the right time, and you'll be unstoppable."}]},{"id":"train-998070","title":"Advanced Techniques","sub":"Training lesson · variant 3","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"While Weapon Mastery: Distorted Desires is active, every 11th attack on combatants inflicted with Misfortune will result in an Accident, dealing additional damage and generating Corruption."}]},{"id":"train-998006","title":"Advanced Techniques","sub":"Training lesson · variant 4","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"After activating Weapon Mastery: Wolf's Combustion, shooting a combatant ignited by Wolf's Ignition deals additional Solar damage. Using Signature Ability: Wolf's Flames inflicts Wolf's Ignition on the target."}]},{"id":"train-998072","title":"Advanced Techniques","sub":"Training lesson · variant 5","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"While Weapon Mastery: Thunderous Reveal is active, weapon hits will detonate Aftermath marks, with each detonation reducing the combatant's stacks by 1."}]},{"id":"train-998008","title":"Mechanic Tutorial","sub":"Training lesson · variant 5","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Resistor Barricade to create an arc-shaped barrier in front of you. The barrier will block incoming projectiles, but you can still fire at combatants through it."}]},{"id":"train-998073","title":"Trial: Umeko","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Umeko"}]},{"id":"train-998009","title":"Advanced Techniques","sub":"Training lesson · variant 6","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"After activating Weapon Mastery: Safeguard Lightning, bullets fired through the Resistor Barricade deal Chain Lightning damage to combatants."}]},{"id":"train-998087","title":"Mechanic Tutorial","sub":"Training lesson · variant 6","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Rapid Deployment to deploy a Healing Drone and Boosting Drone. Casting the ability again upgrades the drone."}]},{"id":"train-998088","title":"Advanced Techniques","sub":"Training lesson · variant 7","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Casting Salvo grants the Overclocked Shot effect for the next 6s, shortening draw/charge times for weapons and dealing additional Arc damage to hit combatants."}]},{"id":"train-998076","title":"Advanced Techniques","sub":"Training lesson · variant 8","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Voidstep to become invisible and gain a Void array that can be used to heal allies. Break the combatants' Tangled Void to restore Umeko's health more rapidly."}]},{"id":"train-998012","title":"Mechanic Tutorial","sub":"Training lesson · variant 7","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Gravitational Collapse to group surrounding combatants. Follow up with Signature Ability: Gemini Satellite to maximize the damage."}]},{"id":"train-998013","title":"Advanced Techniques","sub":"Training lesson · variant 9","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"After activating Weapon Mastery: Neutron Rebirth, every combatant hit by your abilities grants a stack of Neutron Rebirth. Consuming Neutron Rebirth grants Ikora's next shot an additional hit of AoE damage."}]},{"id":"train-998014","title":"Mechanic Tutorial","sub":"Training lesson · variant 8","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Tan-2 has two modes: In Dawnstar mode, he can cast Signature Ability: Sunrise to heal himself or allies. In Duskstar mode, he can cast Signature Ability: Sunset to inflict Disable Heal and Scorch on combatants."}]},{"id":"train-998015","title":"Advanced Techniques","sub":"Training lesson · variant 10","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Using firearms to deal damage to combatants accumulates Flare. When Flare is fully charged, the next Signature Ability: Sunset/Sunrise will be enhanced. After activating Weapon Mastery: Phosphorus, casting an enhanced Signature Ability grants Phosphorus, which adds an additional hit of damage to shots."}]},{"id":"train-998086","title":"Trial: Helhest","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Helhest"}]},{"id":"train-998089","title":"Trial: Jaren","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Jaren"}]},{"id":"train-998019","title":"Advanced Techniques","sub":"Training lesson · variant 11","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"After activating Weapon Mastery: Arc Overload, casting abilities grants Arc Overload. Each shot consumes 1 stack of Arc Overload to deal Chain Lightning damage."}]},{"id":"train-998020","title":"Mechanic Tutorial","sub":"Training lesson · variant 9","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Casting Signature Ability: Abyss Engulf generates a barrier, consuming bullets and blast energy to grant Maru an overshield and Resonance. When Resonance exceeds 50%, Maru's abilities will be enhanced."}]},{"id":"train-998021","title":"Advanced Techniques","sub":"Training lesson · variant 12","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"After activating Weapon Mastery: Blast Resonance, when Resonance exceeds 50%, after a weapon's blast hits, it generates split shells that deal additional damage."}]},{"id":"train-998090","title":"Mechanic Tutorial","sub":"Training lesson · variant 10","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Use Signature Ability: Blazing Shot to quickly defeat groups of base combatants or deal a heavy blow to lone elites. Use Signature Ability: Emergency Evasion to blind groups of combatants and leap in the direction you're moving in."}]},{"id":"train-998091","title":"Advanced Techniques","sub":"Training lesson · variant 13","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Entering the Stag Protection state will enhance weapons with overflowing Light. Welling Light grants shots a lock-on effect, guaranteeing precision damage."}]},{"id":"train-998032","title":"Rapid-Fire Shinka","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"These combatants have a special damage resistance mechanic that can usually be disabled by hitting the enemy many times. Can be countered with Rapid-Fire weapons (Primary Weapon: Auto Rifles, Pulse Rifles, or Submachine Guns; Power Weapon: Machine Guns or Auto Crossbows)."}]},{"id":"train-997904","title":"Mechanic Tutorial","sub":"Training lesson · variant 11","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Landing hits with Signature Ability: Stellar Projection or hitting multiple combatants with a single weapon shot grants stacks of Annihilating Light. When stacks are full, casting Void Traversal applies Void Annihilation, which allows for another immediate cast of the Signature Ability."}]},{"id":"train-998033","title":"Impact Shinka","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"These combatants have a specific damage resistance mechanic that can usually be disabled by close-range attacks. Can be countered with Impact weapons (Primary Weapon: Fusion Rifles or Sidearms; Power Weapon: Shotguns or Swords)."}]},{"id":"train-997905","title":"Advanced Techniques","sub":"Training lesson · variant 14","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Landing hits with Signature Ability: Stellar Projection triggers an additional Volatile Blast on combatants inflicted with Volatile Energy or Volatile Prism. Launching more than 2 Micro Black Holes in a single activation expands their collapse radius, recharging this Signature Ability on hit."}]},{"id":"train-998031","title":"Piercing Shinka","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"These combatants have a special damage resistance mechanic that can usually be disabled by hitting specific parts quickly. Can be countered with Piercing weapons (Primary Weapon: Scout Rifles or Hand Cannons; Power Weapon: Sniper Rifles, Linear Fusion Rifles)."}]},{"id":"train-997903","title":"Trial Character: Ikora, the Hidden.","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial Character: Ikora, the Hidden."}]},{"id":"train-998035","title":"Advanced Techniques","sub":"Training lesson · variant 15","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Signature Ability: Luminous Barrier gains 1 stack of Drifting Energy. When Scout Rifle or Linear Fusion Rifle shots pierce it, they will deal an additional instance of damage. Once Weapon Mastery Lv.4 is activated, shots fired through newly created barriers will generate additional chain lightning, dealing damage to multiple nearby combatants."}]},{"id":"train-997907","title":"Mechanic Tutorial","sub":"Training lesson · variant 12","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Lightning Catcher to throw a javelin. Hitting targets deals damage, knocks the target back, and inflicts Blind. Cast Competition Time to perform a rapid dodge, after which landing shots grants points that offset damage taken."}]},{"id":"train-998036","title":"Trial: Kabr, the Resolute.","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Kabr, the Resolute."}]},{"id":"train-997908","title":"Advanced Techniques","sub":"Training lesson · variant 16","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"When shots hit targets affected by a Thunderous Javelin's control effects, they trigger a lightning burst. Each Thunderous Javelin holds up to 6 Electrostatic Energy charges."}]},{"id":"train-998034","title":"Mechanic Tutorial","sub":"Training lesson · variant 13","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Luminous Barrier to summon a barrier that blocks incoming projectiles and knocks combatants in front of it back. Cast Radiant Thunder to deal Arc damage to combatants and accumulate Blind duration."}]},{"id":"train-997906","title":"Trial: Efrideet","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Efrideet"}]},{"id":"train-998030","title":"Spread Shinka","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"These combatants have a special damage resistance mechanic that can usually be disabled by hitting multiple parts at the same time. Can be countered with Spread weapons (Primary Weapon: Light Grenade Launchers; Power Weapon: Grenade Launchers or Rocket Launchers)."}]},{"id":"train-998050","title":"Trial: Ikora","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Ikora"}]},{"id":"train-998051","title":"Trial: Kabr","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Kabr"}]},{"id":"train-998052","title":"Trial: Maru","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Maru"}]},{"id":"train-998053","title":"Trial: Estela","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Estela"}]},{"id":"train-998054","title":"Trial: Attal","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Attal"}]},{"id":"train-998055","title":"Trial: Finnala","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Finnala"}]},{"id":"train-998056","title":"Trial: Gwynn","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Gwynn"}]},{"id":"train-998057","title":"Trial: Jolder","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Jolder"}]},{"id":"train-998058","title":"Trial: Ning Fei","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Ning Fei"}]},{"id":"train-998059","title":"Trial: Xuan Wei","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Xuan Wei"}]},{"id":"train-998060","title":"Trial: Tan-2","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Tan-2"}]},{"id":"train-998061","title":"Mechanic Tutorial","sub":"Training lesson · variant 14","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Charge Signature Ability: Funerary Flames to enhance its effects, granting high damage resistance."}]},{"id":"train-998062","title":"Advanced Techniques","sub":"Training lesson · variant 17","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"While Weapon Mastery: Fiery Empowerment is active, shots that hit combatants will inflict Scorch, and defeated targets will drop Firesprites."}]},{"id":"train-998063","title":"Mechanic Tutorial","sub":"Training lesson · variant 15","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Void Dance to unleash all held Void Spirits. Void Spirits will track and deal damage to combatants."}]},{"id":"train-998064","title":"Advanced Techniques","sub":"Training lesson · variant 18","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Combatants hit with weapons drop Void Spirits."}]},{"id":"train-998067","title":"Mechanic Tutorial","sub":"Training lesson · variant 16","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Casting Signature Ability: Arc Missile generates a projectile that ricochets between targets, dealing damage and inflicting Serenity. Targets hit multiple times will be blinded."}]},{"id":"train-998071","title":"Mechanic Tutorial","sub":"Training lesson · variant 17","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Casting Signature Ability: Mighty Tether or Signature Ability: Fist of the Warpath will inflict combatants with Aftermath."}]},{"id":"train-998074","title":"Trial: Rossi-11","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Trial: Rossi-11"}]},{"id":"train-998075","title":"Mechanic Tutorial","sub":"Training lesson · variant 18","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Shadow Shuriken to inflict combatants with Shadow's Curse and deal Void damage. Inflict 3 or more stacks to confine combatants. Use your Scout Rifle to accumulate Shadow Energy more efficiently."}]},{"id":"train-998077","title":"Mechanic Tutorial","sub":"Training lesson · variant 19","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Cast Signature Ability: Arc Cage to pull in and confine nearby combatants, then generate an spherical barrier that blocks projectile damage. Activate Weapon Mastery: Ionic Cascade to charge weapons, granting an additional damage increase."}]},{"id":"train-998078","title":"Advanced Techniques","sub":"Training lesson · variant 19","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Fire at combatants after casting Signature Ability: Thread Flow to deal additional damage."}]},{"id":"train-998079","title":"Race Trait - Fallen","sub":"Training lesson","quality":null,"art":null,"filters":{"Kind":"Training lesson"},"body":[{"p":"Fallen combatants can blink, dash, and sprint to evade projectiles or maneuver across the battlefield. Use confinement-type abilities to render them immobile."}]}];